{"code": "from math import atan, pi

def partial_sum(N):
    s = 0.0
    for n in range(1, N + 1):
        s += atan(1.0 / (2 * n * n))
    return s

target = pi / 4
print(f"Target value: {target}")
for N in [10, 100, 1000, 10000]:
    s = partial_sum(N)
    print(f"N={N}, Sum={s}, Error={abs(s - target)}")"}
